#define main e97_original_main
#include "evaluate.cpp"
#undef main
#include <faiss/IndexFlat.h>
#include <sys/time.h>
#include <signal.h>
#include <ucontext.h>
#include <dlfcn.h>
const float* diagnosis_base=nullptr;
size_t diagnosis_dim=0;
static uintptr_t pcs[200000];
static volatile sig_atomic_t pc_count=0;
static void sample_handler(int,siginfo_t*,void* ctx){int i=pc_count;if(i<200000){pcs[i]=((ucontext_t*)ctx)->uc_mcontext.gregs[REG_RIP];pc_count=i+1;}}
static void sampler(bool on){struct itimerval t{};if(on){pc_count=0;struct sigaction a{};a.sa_sigaction=sample_handler;a.sa_flags=SA_SIGINFO;sigemptyset(&a.sa_mask);require(sigaction(SIGPROF,&a,nullptr)==0,"sigaction");t.it_interval.tv_usec=1000;t.it_value.tv_usec=1000;}require(setitimer(ITIMER_PROF,&t,nullptr)==0,"setitimer");}
static json saved_samples(){std::map<uintptr_t,size_t> hist;for(int i=0;i<pc_count;++i)++hist[pcs[i]];json a=json::array();for(auto [pc,n]:hist){Dl_info d{};dladdr((void*)pc,&d);a.push_back({{"pc",pc},{"count",n},{"file",d.dli_fname?d.dli_fname:""},{"symbol",d.dli_sname?d.dli_sname:""},{"base",uintptr_t(d.dli_fbase)}});}return {{"samples",pc_count},{"histogram",a}};}
static void reference(const Batch& b,const fs::path& path){require(b.ids==read_raw<int32_t>(path/"ids.i32"),"E97 result IDs mismatch");auto dist=read_raw<float>(path/"distances.f32");require(dist.size()==b.dist.size()&&!memcmp(dist.data(),b.dist.data(),dist.size()*4),"E97 distance bits mismatch");require(b.entries==read_raw<int32_t>(path/"entry_ids.i32"),"E97 entries mismatch");}
static json stages(Worker& w,Router& router,HNSW& full,const std::vector<float>& q,size_t d,Batch& b,bool hnsw){double route=0,setup=0,graph=0,output=0;auto all=Clock::now();for(size_t i=0;i<b.n;++i){const float* query=q.data()+i*d;if(hnsw){auto t=Clock::now();auto heap=full.searchKnn(query,b.k);graph+=seconds(t);t=Clock::now();for(int j=int(b.k)-1;j>=0;--j){b.ids[i*b.k+j]=heap.top().second;b.dist[i*b.k+j]=heap.top().first;heap.pop();}output+=seconds(t);}else{auto t=Clock::now();auto entries=router.route(query);route+=seconds(t);t=Clock::now();std::copy(entries.begin(),entries.end(),b.entries.begin()+i*3);w.ep.clear();for(int id:entries)w.ep.emplace_back(id,1.);w.vt.advance();w.plain->set_query(query);setup+=seconds(t);t=Clock::now();w.index.acsg.search_new(*w.plain,b.k,w.ids.data(),b.dist.data()+i*b.k,w.vt,2,w.ep,&w.ret);graph+=seconds(t);t=Clock::now();for(size_t j=0;j<b.k;++j)b.ids[i*b.k+j]=w.ids[j];output+=seconds(t);}}
 return {{"wall_seconds",seconds(all)},{"route_seconds",route},{"setup_seconds",setup},{"graph_seconds",graph},{"output_seconds",output},{"parity",true}};}
static json kernel_bench(const std::vector<float>& q,size_t d,faiss::IndexFlat& flat,hnswlib::SpaceInterface<float>& space){constexpr size_t N=1000000;std::vector<uint32_t> ix(N);uint64_t seed=0x12345678;for(auto& i:ix){seed=seed*6364136223846793005ULL+1;i=(seed>>32)%flat.ntotal;}auto fn=space.get_dist_func();auto param=space.get_dist_func_param();json out=json::array();volatile double sink=0;for(bool hot:{true,false}){for(int rep=-1;rep<3;++rep){for(bool h:{false,true}){auto t=Clock::now();double sum=0;for(size_t i=0;i<N;++i){const float* x=flat.get_xb()+size_t(hot?ix[i]%815:ix[i])*d;const float* y=q.data()+(i%16)*d;sum+=h?fn(y,x,param):faiss::fvec_inner_product(y,x,d);}sink=sum;double sec=seconds(t);if(rep>=0)out.push_back({{"hot_815",hot},{"hnsw",h},{"repeat",rep},{"seconds",sec},{"checksum",sum},{"calls",N}});}}}Dl_info info{};dladdr((void*)fn,&info);return {{"measurements",out},{"hnsw_function_pc",uintptr_t(fn)},{"dimension",d},{"note","Identical base addresses and query stream; HNSW returns 1-IP, Faiss IP. Microbenchmark is not search QPS."}};}
int main(int argc,char**argv){try{require(argc==4,"diagnose config output variant");threads();json c=read_json(argv[1]);fs::path out=argv[2];std::string variant=argv[3];require(!fs::exists(out/"complete.json"),"already complete");fs::create_directories(out);write_json(out/"config.json",c);auto idx=load_nsg(c["index"]);size_t d=idx->d,n=c["n"];require(n==10000&&d==512&&idx->metric_type==0,"WebVid contract");auto* flat=dynamic_cast<faiss::IndexFlat*>(idx->storage);require(flat,"flat storage");diagnosis_base=flat->get_xb();diagnosis_dim=d;Fvecs fq(c["queries"]);require(fq.n==n&&fq.d==d,"query shape");std::vector<float> q(n*d);for(size_t i=0;i<n;++i)std::copy(fq.row(i),fq.row(i)+d,q.data()+i*d);
 Router router(c["soft"],d,c["router"].get<std::string>());auto space=make_space(0,d);CountParam hc{space->get_dist_func(),space->get_dist_func_param(),0};std::unique_ptr<HNSW> full;if(variant=="original"){Fvecs base(c["base"]);full=load_topology(c["hnsw_topology"].get<std::string>(),base,space.get());}Worker worker(*idx);struct rusage usage;getrusage(RUSAGE_SELF,&usage);require(usage.ru_maxrss<64LL*1024*1024,"64GiB RSS");threads();json results=json::array();uint64_t calls=0;
 std::vector<std::pair<int,int>> cases=variant=="original"?std::vector<std::pair<int,int>>{{100,100},{100,400},{100,1250},{1,1250}}:std::vector<std::pair<int,int>>{{100,1250}};
 for(auto [K,L]:cases){idx->acsg.search_L=L;if(full)full->setEf(L);std::vector<std::string> methods=full?std::vector<std::string>{"GT10-soft-t1","HNSW"}:std::vector<std::string>{"GT10-soft-t1"};std::map<std::string,std::unique_ptr<Batch>> baselines;std::map<std::string,std::vector<double>> timings;
 for(auto method:methods){Batch warm(n,K);worker.run(method,method=="HNSW"?nullptr:&router,full.get(),hc,q,d,warm,false);calls+=n;reference(warm,fs::path(c["e97_results"].get<std::string>())/("k"+std::to_string(K))/(method+"_L"+std::to_string(L)));baselines[method]=std::make_unique<Batch>(warm);std::cout<<"PARITY "<<variant<<" "<<method<<" K"<<K<<" L"<<L<<std::endl;}
 for(int rep=0;rep<3;++rep){auto order=methods;if(rep%2)std::reverse(order.begin(),order.end());for(auto method:order){Batch b(n,K);threads();auto t=Clock::now();worker.run(method,method=="HNSW"?nullptr:&router,full.get(),hc,q,d,b,false);double sec=seconds(t);calls+=n;same(*baselines.at(method),b);timings[method].push_back(sec);json r={{"variant",variant},{"method",method},{"K",K},{"L",L},{"repeat",rep},{"seconds",sec},{"qps",n/sec},{"parity",true}};results.push_back(r);write_json(out/"timing_progress.json",results);std::cout<<r.dump()<<std::endl;}}
 if(variant=="original"&&K==100&&L==1250){for(auto method:methods){Batch b(n,K);auto stage=stages(worker,router,*full,q,d,b,method=="HNSW");calls+=n;same(*baselines.at(method),b);write_json(out/(method+".stages.json"),stage);std::cout<<"STAGES "<<method<<" "<<stage.dump()<<std::endl;Batch sampled(n,K);sampler(true);auto t=Clock::now();worker.run(method,method=="HNSW"?nullptr:&router,full.get(),hc,q,d,sampled,false);double sec=seconds(t);sampler(false);calls+=n;same(*baselines.at(method),sampled);auto samples=saved_samples();samples["wall_seconds"]=sec;samples["parity"]=true;write_json(out/(method+".samples.json"),samples);std::cout<<"SAMPLED "<<method<<" "<<sec<<" "<<pc_count<<std::endl;}}}
 if(variant=="original")write_json(out/"kernels.json",kernel_bench(q,d,*flat,*space));getrusage(RUSAGE_SELF,&usage);write_json(out/"complete.json",{{"status","PASS"},{"variant",variant},{"threads",process_threads()},{"cpu",15},{"search_calls",calls},{"maxrss_kib",usage.ru_maxrss},{"timings",results},{"e97_bit_parity",true}});std::cout<<"COMPLETE "<<variant<<" calls="<<calls<<std::endl;return 0;}catch(const std::exception& e){sampler(false);std::cerr<<e.what()<<std::endl;return 1;}}
